   435  void SubMac::SampleRssi(void)
   436  {
   437      int8_t rssi = GetRssi();
   438
   439      if (rssi != kInvalidRssiValue)
   440      {
   441          if ((mEnergyScanMaxRssi == kInvalidRssiValue) || (rssi > mEnergyScanMaxRssi))
   442          {
   443              mEnergyScanMaxRssi = rssi;
   444          }
   445      }
   446
   447      if (TimerMilliScheduler::IsStrictlyBefore(TimerMilli::GetNow(), mEnergyScanEndTime))
   448      {
   449          mTimer.StartAt(mTimer.GetFireTime(), kEnergyScanRssiSampleInterval);
   450      }
   451      else
   452      {
   453          HandleEnergyScanDone(mEnergyScanMaxRssi);
   454      }
   455  }
