   468  void SubMac::HandleTimer(void)
   469  {
   470      switch (mState)
   471      {
   472      case kStateCsmaBackoff:
   473          BeginTransmit();
   474          break;
   475
   476      case kStateTransmit:
   477          otLogDebgMac("Ack timer timed out");
   478          otPlatRadioReceive(&GetInstance(), mTransmitFrame.GetChannel());
   479          HandleTransmitDone(mTransmitFrame, NULL, OT_ERROR_NO_ACK);
   480          break;
   481
   482      case kStateEnergyScan:
   483          SampleRssi();
   484          break;
   485
   486      default:
   487          break;
   488      }
   489  }
